                    <div class="wheel-spoke" style="transform: rotate(0deg)"></div>
                    <div class="wheel-spoke" style="transform: rotate(60deg)"></div>
                    <div class="wheel-spoke" style="transform: rotate(120deg)"></div>
                    <div class="wheel-spoke" style="transform: rotate(180deg)"></div>
                    <div class="wheel-spoke" style="transform: rotate(240deg)"></div>
                    <div class="wheel-spoke" style="transform: rotate(300deg)"></div>
                </div>
                <div class="pedal"></div>
            </div>
        </div>
    </div>
</body>
</html>
